class Solution {
  public int findDistance(TreeNode root, int p, int q) {
    TreeNode lca = lca(root, p, q);
    return depth(lca, p, 0) + depth(lca, q, 0);
  }

  private TreeNode lca(TreeNode node, int p, int q) {
    if (node == null || node.val == p || node.val == q) return node;
    TreeNode l = lca(node.left, p, q), r = lca(node.right, p, q);
    return l != null && r != null ? node : l != null ? l : r;
  }

  private int depth(TreeNode node, int target, int d) {
    if (node == null) return -1;
    if (node.val == target) return d;
    int l = depth(node.left, target, d + 1);
    return l >= 0 ? l : depth(node.right, target, d + 1);
  }
}
